import{_ as l,a0 as o,w as p,s as d,ao as h,I as e,x as i,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"既然float不能表示所有的int，那為什麼在類型轉換時C++將int轉換成float？ | LCTT x X-CMD","titleTemplate":false,"description":"既然float不能表示所有的int，那為什麼在類型轉換時C++將int轉換成float？ | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"既然float不能表示所有的int，那為什麼在類型轉換時C++將int轉換成float？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"既然float不能表示所有的int，那為什麼在類型轉換時C++將int轉換成float？ | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150124 Why does C++ promote an int to a float when a float cannot represent all int values","title":"既然float不能表示所有的int，那為什麼在類型轉換時C++將int轉換成float？","tag":"201505","desc":""},"relativePath":"201505/20150124 Why does C++ promote an int to a float when a float cannot represent all int values.md","filePath":"[post].md"}'),r={name:"201505/20150124 Why does C++ promote an int to a float when a float cannot represent all int values.md"};function k(f,t,u,g,C,E){const s=o("Link");return p(),d("div",null,[t[13]||(t[13]=h(`<h1 id="既然float不能表示所有的int-那為什麼在類型轉換時c-將int轉換成float" tabindex="-1">既然float不能表示所有的int，那為什麼在類型轉換時C++將int轉換成float？ <a class="header-anchor" href="#既然float不能表示所有的int-那為什麼在類型轉換時c-將int轉換成float" aria-label="Permalink to “既然float不能表示所有的int，那為什麼在類型轉換時C++將int轉換成float？”">​</a></h1><p>###問題：</p><p>代碼如下：</p><div class="language-C"><button title="Copy Code" class="copy"></button><span class="lang">C</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 23</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> f </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3.14</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> f)</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 執行某段代碼</span></span></code></pre></div><p>編譯器會將i轉換成float類型，然後比較這兩個float的大小，但是float能夠表示所有的int嗎？為什麼沒有將int和float轉換成double類型進行比較呢？</p><p>###回答：</p><p>在整型數的演變中，當<code>int</code>變成<code>unsigned</code>時，會丟掉負數部分（有趣的是，這樣的話，<code>0u &lt; -1</code>就是對的了）。</p><p>和C語言中的大部分機制（在C++中得到繼承）一樣，就硬件操作而言，常見的算術轉換應該簡明易懂。C語言的發明者精通他們所使用機器上的彙編語言，他們編寫的C語言對他們和像他們一樣編寫程序的人有直接的意義，直到使用匯編語言編寫（諸如UNIX內核）的程序時。</p><p>現如今，一般來説，處理器並不具有混合類型的指令系統（如float和double相加、比較int和float，諸如此類），因為如果這樣做造成芯片晶圓的巨大浪費——如果你想支持更多不同的類型，你不得不實現更多的操作碼。然而，在實際中，你只有實現&quot;add int to int&quot;、&quot;compare float to float&quot;和&quot;multiply unsigned with unsigned&quot;等功能的常見指令，這使得優先進行算術轉換變得很有必要——它們是指令系統中兩種類型的映射關係，它們中的大部分很有用處。</p><p>從習慣編寫低級別機器代碼的編程人員的角度來説，如果有了混合類型，那麼在一般情況下最有可能使用的彙編指令就是那些只需要進行最少類型轉換的指令。其中，有一種特殊情況就是浮點數的轉換，特別是在20世紀70年代早期，當時C語言正在被開發，計算機運行速度很慢，而浮點數的計算是通過軟件完成的，所以進行轉換的成本很高。這拖慢了常用算術運算的轉換開發——當時只有一種操作數實現了轉換（這個例外就是long到unsigned int的轉換，這種轉換沒有任何要求，在大部分機器上都可以進行。當然並不是全部，因為總有例外情況）。</p><p>所以，編寫常用的算術轉換是為了完成彙編程序員在大部分時間需要做的事情：即有兩種不匹配的類型，將一種轉換成另一種。這也就是彙編代碼所做的事情，除非有特別原因需要進行其它類型轉換。對於那些習慣編寫彙編代碼的人來説，除非是特殊需要，才會被迫去編寫一種不同的類型轉換。顯然，這種情況下提出編寫轉換是很自然的事情。雖然，你可以簡單地寫成這樣</p><div class="language-C"><button title="Copy Code" class="copy"></button><span class="lang">C</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) f)</span></span></code></pre></div><p>順便提一下，在這個問題中有趣的是，<code>unsigned</code>的優先級高於<code>int</code>，所以把<code>int</code>和<code>unsigned</code>進行比較時，最終進行的是unsigned類型的比較（開頭提到的<code>0u &lt; -1</code>就是這個道理）。我猜測這可能是在早些時候（計算機發展初期），當時的人們認為<code>unsigned</code>比<code>int</code>在所表示的數值範圍上受到的限制更小：現在還不需要符號位，所以可以使用額外的位來表示更大的數值範圍。如果你覺得<code>int</code>可能會溢出，那麼就使用unsigned好了——在使用16位表示的ints時這個擔心會更明顯。</p><hr>`,14)),e("p",null,[t[1]||(t[1]=i("via: ",-1)),a(s,{href:"http://stackoverflow.com/questions/28010565/why-does-c-promote-an-int-to-a-float-when-a-float-cannot-represent-all-int-val/28011249#28011249"},{default:n(()=>[...t[0]||(t[0]=[i("stackoverflow",-1)])]),_:1})]),e("p",null,[t[5]||(t[5]=i("作者：",-1)),a(s,{href:"http://stackoverflow.com/users/4301306/wintermute"},{default:n(()=>[...t[2]||(t[2]=[i("wintermute",-1)])]),_:1}),t[6]||(t[6]=i(" 譯者：",-1)),a(s,{href:"https://github.com/KayGuoWhu"},{default:n(()=>[...t[3]||(t[3]=[i("KayGuoWhu",-1)])]),_:1}),t[7]||(t[7]=i(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:n(()=>[...t[4]||(t[4]=[i("wxy",-1)])]),_:1})]),e("p",null,[t[10]||(t[10]=i("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[i("LCTT",-1)])]),_:1}),t[11]||(t[11]=i(" 原創翻譯，",-1)),a(s,{href:"http://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[i("Linux中國",-1)])]),_:1}),t[12]||(t[12]=i(" 榮譽推出",-1))])])}const b=l(r,[["render",k]]);export{c as __pageData,b as default};
